<?php require 'config.php';role_required(['requester','admin']);$materials=db()->query("SELECT * FROM materials WHERE active=1 ORDER BY name")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$ids=$_POST['material_id']??[];$qtys=$_POST['qty']??[];$notes=$_POST['note']??[];$purpose=trim($_POST['purpose']??'');$valid=[];foreach($ids as $i=>$mid){$q=(float)($qtys[$i]??0);if((int)$mid>0&&$q>0)$valid[]=[(int)$mid,$q,trim($notes[$i]??'')];}if(!$valid){flash('error',current_lang()==='th'?'กรุณาเพิ่มรายการพัสดุ':'Please add at least one material.');}else{try{$pdo=db();$pdo->beginTransaction();$no='REQ-'.date('YmdHis').'-'.random_int(100,999);$pdo->prepare("INSERT INTO requests(request_no,requester_id,department,purpose,status,current_level) VALUES(?,?,?,?,'pending',1)")->execute([$no,user()['id'],user()['department'],$purpose]);$rid=(int)$pdo->lastInsertId();$it=$pdo->prepare("INSERT INTO request_items(request_id,material_id,qty,note) VALUES(?,?,?,?)");foreach($valid as $v)$it->execute([$rid,$v[0],$v[1],$v[2]]);$st=$pdo->prepare("INSERT INTO approval_steps(request_id,level_no,role_code) VALUES(?,?,?)");foreach(['dept_head','procurement','director'] as $i=>$role)$st->execute([$rid,$i+1,$role]);log_action($rid,user()['id'],'CREATE','Created requisition '.$no);$pdo->commit();redirect("request_view.php?id=$rid");}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}}}$msg=flash();?><!doctype html><html lang="<?=e(current_lang())?>"><head><?php include 'partials/head.php';?></head><body><?php include 'partials/nav.php';?><main class="container"><div class="page-head"><div><h2><?=e(t('new_request'))?></h2><p><?=current_lang()==='th'?'สร้างคำขอเบิกและส่งเข้าสู่กระบวนการอนุมัติ 3 ระดับ':'Create a requisition and submit it to the 3-level approval workflow.'?></p></div></div><?php if($msg):?><div class="alert <?=e($msg[0])?>"><?=e($msg[1])?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label><?=e(t('purpose'))?></label><textarea name="purpose" required placeholder="<?=current_lang()==='th'?'ระบุวัตถุประสงค์ในการเบิก':'Describe the purpose of this request'?>"></textarea><h3><?=e(t('items'))?></h3><div id="items"><div class="row item"><div><label><?=e(t('material'))?></label><select name="material_id[]" required><option value="">-- Select --</option><?php foreach($materials as $m):?><option value="<?=$m['id']?>"><?=e($m['code'].' - '.$m['name'].' ('.$m['stock'].' '.$m['unit'].')')?></option><?php endforeach;?></select></div><div><label><?=e(t('quantity'))?></label><input type="number" step="0.01" min="0.01" name="qty[]" required></div><div><label><?=e(t('note'))?></label><input name="note[]"></div></div></div><br><button type="button" class="secondary" onclick="addItem()">＋ <?=e(t('add_item'))?></button> <button class="success">✓ <?=e(t('submit'))?></button></form><script>function addItem(){const x=document.querySelector('.item').cloneNode(true);x.querySelectorAll('input').forEach(i=>i.value='');x.querySelector('select').selectedIndex=0;document.getElementById('items').appendChild(x)}</script></main></div></div></body></html>
